initial_condition:
with {
    the SUT containing a Hosted @context and the default Cached Core Context.
        }

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Serve a @context with Response Status Code set to 404     and
        Serve a @context with Response reason set to 'Not Found'     and
        Serve a @context with Response Body containing the type '${ERROR_TYPE_RESOURCE_NOT_FOUND}' and Response Body Title is a string and is not ${EMPTY} and Response Body Detail is a string and is not ${EMPTY} and Response Boty Title is not equal to Response Body Detail
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/jsonldContexts/{contextId}'
        method set to 'GET'
        Serve a @context with contextID 'wrong_id_context' and details 'true'
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Serve a @context with Response Status Code set to 400     and
        Serve a @context with Response reason set to 'Bad Request'     and
        Serve a @context with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/BadRequestData' and Response Body Title is a string and is not ${EMPTY} and Response Body Detail is a string and is not ${EMPTY} and Response Boty Title is not equal to Response Body Detail
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/jsonldContexts/{contextId}'
        method set to 'GET'
        Serve a @context with contextID '${uri}' and details 'other'
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Serve a @context with Response Status Code set to 422     and
        Serve a @context with Response reason set to 'Unprocessable Content'     and
        Serve a @context with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/OperationNotSupported' and Response Body Title is a string and is not ${EMPTY} and Response Body Detail is a string and is not ${EMPTY} and Response Boty Title is not equal to Response Body Detail
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/jsonldContexts/{contextId}'
        method set to 'GET'
        Serve a @context with contextID 'https://uri.etsi.org/ngsi-ld/v1/ngsi-ld-core-context-v1.6.jsonld' and details 'false'
}
